SET default_transaction_read_only = on;
SELECT jsonb_build_object(
  'legacy_record_types', (SELECT jsonb_agg(code) FROM public.legacy_record_types),
  'test_qb_rows', (SELECT jsonb_agg(jsonb_build_object('id',id::text,'user_id',user_id::text,'posted_date',posted_date,'amount',amount,'description',description,'client_entity_id',client_entity_id::text,'ledger_book_id',ledger_book_id::text,'synced_from_qb_at',synced_from_qb_at)) FROM public.qb_transactions WHERE description ILIKE '%4FB-CANONICAL-TEST%' OR description ILIKE '%CANONICAL-TEST%'),
  'audit_actions_all', (SELECT jsonb_agg(jsonb_build_object('action',action,'n',n) ORDER BY n DESC) FROM (SELECT action, count(*) n FROM public.reconciliation_audit_log GROUP BY action) t),
  'audit_actions_dup', (SELECT jsonb_agg(jsonb_build_object('action',action,'n',n) ORDER BY n DESC) FROM (SELECT a.action, count(*) n FROM public.reconciliation_audit_log a JOIN (SELECT m.id FROM public.reconciliation_matches m JOIN (SELECT qb_transaction_id FROM public.reconciliation_matches WHERE matched_by='auto' AND qb_transaction_id IS NOT NULL GROUP BY qb_transaction_id HAVING count(*)>1) d ON d.qb_transaction_id=m.qb_transaction_id WHERE m.matched_by='auto') m2 ON m2.id=a.reconciliation_match_id GROUP BY a.action) t),
  'approved_by_values', (SELECT jsonb_agg(jsonb_build_object('approved_by',approved_by,'n',n) ORDER BY n DESC) FROM (SELECT approved_by, count(*) n FROM public.reconciliation_matches WHERE approved_at IS NOT NULL GROUP BY approved_by) t),
  'confidence_buckets_dup', (SELECT jsonb_agg(jsonb_build_object('bucket',bucket,'n',n) ORDER BY bucket) FROM (SELECT CASE WHEN confidence < 0.4 THEN 'lt0.4' WHEN confidence < 0.7 THEN '0.4-0.7' ELSE 'gte0.7' END bucket, count(*) n FROM public.reconciliation_matches m JOIN (SELECT qb_transaction_id FROM public.reconciliation_matches WHERE matched_by='auto' AND qb_transaction_id IS NOT NULL GROUP BY qb_transaction_id HAVING count(*)>1) d ON d.qb_transaction_id=m.qb_transaction_id WHERE m.matched_by='auto' GROUP BY 1) t),
  'matched_day_counts', (SELECT jsonb_agg(jsonb_build_object('dte',dte,'n',n) ORDER BY dte) FROM (SELECT to_char(matched_at,'YYYY-MM-DD') dte, count(*) n FROM public.reconciliation_matches GROUP BY 1) t),
  'audit_actor_values', (SELECT jsonb_agg(jsonb_build_object('action_by',action_by,'n',n) ORDER BY n DESC) FROM (SELECT action_by, count(*) n FROM public.reconciliation_audit_log GROUP BY action_by) t)
) AS result;
